"""
XnAP Protocol Messages Definition Module for PCAP Analysis.
This module provides predefined XnAP (Xn Application Protocol) message definitions and factory functions
for creating awaited messages used in PCAP file analysis.
The module defines AwaitedMessage objects that can be used to verify the presence and correctness of
specific XnAP protocol messages in network traffic captures.

:copyright:     Nokia Networks
:author:        Piotr Brzezicki, Mateusz Potoniec
:maintainer:    Piotr Brzezicki, Mateusz Potoniec
:contact:       piotr.brzezicki@nokia.com, mateusz.potoniec@nokia.com

Usage:
    from taf.rfrl.utilities.parsers.pcap_checker import Checker
    from taf.rfrl.utilities.parsers.pcap_checker.utils import PcapProvider
    from taf.rfrl.utilities.parsers.pcap_checker.messages import xnap_messages

    awaited_messages = [
        xnap_messages.SNODE_ADD_REQUEST_ALLOWED_BC,
        xnap_messages.SNODE_ADD_REQUEST_ACKNOWLEDGE,
        xnap_messages.SNODE_RECONFIGURATION_COMPLETE,
        xnap_messages.SN_STATUS_TRANSFER
    ]

    forbidden_messages = [
        xnap_messages.SNODE_RELEASE_REQUEST,
        xnap_messages.UE_CONTEXT_RELEASE
    ]

    pcap_provider = PcapProvider()
    checker = Checker(pcap_provider=pcap_provider)
    checker.expect_flow(
        pcap_file=pcap_file,
        display_filter='xnap',
        awaited_messages=awaited_messages,
        forbidden_messages=forbidden_messages
    )
"""


from taf.rfrl.utilities.parsers.pcap_checker.checker import AwaitedMessage
from taf.rfrl.utilities.parsers.pcap_checker.inspectors import HasInspector


SNODE_ADD_REQUEST_ALLOWED_BC = AwaitedMessage(
    name='SgNBAdditionRequest',
    find_by=[HasInspector('xnap.SNodeAdditionRequest_element')],
    verify_by=[HasInspector('nr-rrc.allowedBC_ListMRDC')],
)


SNODE_ADD_REQUEST_ACKNOWLEDGE = AwaitedMessage(
    name='SNodeAdditionRequestAcknowledge',
    find_by=[HasInspector('xnap.SNodeAdditionRequestAcknowledge_element')],
    verify_by=[
        HasInspector('nr-rrc.bandCombinationIndex'),
        HasInspector('nr-rrc.requestedFeatureSets'),
    ],
)


XN_U_ADDRESS_INDICATION = AwaitedMessage(
    name='XnUAddressIndication',
    find_by=[HasInspector('xnap.XnUAddressIndication_element')],
    verify_by=[],
)


SN_STATUS_TRANSFER = AwaitedMessage(
    name='SNStatusTransfer',
    find_by=[HasInspector('xnap.SNStatusTransfer_element')],
    verify_by=[],
)


SNODE_RECONFIGURATION_COMPLETE = AwaitedMessage(
    name='SNodeReconfigurationComplete',
    find_by=[HasInspector('xnap.SNodeReconfigurationComplete_element')],
    verify_by=[],
)


SNODE_RELEASE_REQUEST = AwaitedMessage(
    name='SNodeReleaseRequest',
    find_by=[HasInspector('xnap.SNodeReleaseRequest_element')],
    verify_by=[],
)


SNODE_RELEASE_REQUEST_ACKNOWLEDGE = AwaitedMessage(
    name='SNodeReleaseRequestAcknowledge',
    find_by=[HasInspector('xnap.SNodeReleaseRequestAcknowledge_element')],
    verify_by=[],
)


UE_CONTEXT_RELEASE = AwaitedMessage(
    name='UEContextRelease',
    find_by=[HasInspector('xnap.UEContextRelease_element')],
    verify_by=[],
)


RESET_RESPONSE_PARTIAL_MISC_OM_INTERVENTION = AwaitedMessage(
    name='ResetRequest',
    find_by=[HasInspector('xnap.ResetResponse_element')],
    verify_by=[HasInspector('xnap.partialReset_element')],
)


ACTIVITY_NOTIFICATION_INACTIVE = AwaitedMessage(
    name='ActivityNotification',
    find_by=[HasInspector('xnap.ActivityNotification_element')],
    verify_by=[HasInspector('xnap.UserPlaneTrafficActivityReport', '0')],
)


ACTIVITY_NOTIFICATION_REACTIVATED = AwaitedMessage(
    name='ActivityNotification',
    find_by=[HasInspector('xnap.ActivityNotification_element')],
    verify_by=[HasInspector('xnap.UserPlaneTrafficActivityReport', '1')],
)


SNODE_MODIFICATION_REQUIRED = AwaitedMessage(
    name='SNodeModificationRequired',
    find_by=[HasInspector('xnap.SNodeModificationRequired_element')],
    verify_by=[],
)
